import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.BU4O3IzQ.js";const s="/penn-notes/news/2026-08/61f2570a414a.jpg",i="/penn-notes/news/2026-08/8ef5eb21fb40.jpg",o="/penn-notes/news/2026-08/5e7a06a0b2a0.jpg",p="/penn-notes/news/2026-08/b0171128b69a.jpg",c="/penn-notes/news/2026-08/bf95006d68c1.jpg",l="/penn-notes/news/2026-08/9ddb23a6fa90.jpg",h="/penn-notes/news/2026-08/202b72f027d3.png",d="/penn-notes/news/2026-08/d418daa862d5.png",k=JSON.parse('{"title":"AI 动态 · 2026-08-17","description":"","frontmatter":{"title":"AI 动态 · 2026-08-17","date":"2026-08-17T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-17.md","filePath":"news/2026-08/ai-news-2026-08-17.md","lastUpdated":1787416107000}'),m={name:"news/2026-08/ai-news-2026-08-17.md"};function u(w,e,A,I,g,b){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-08-17" tabindex="-1">AI 动态 · 2026-08-17 <a class="header-anchor" href="#ai-动态-·-2026-08-17" aria-label="Permalink to &quot;AI 动态 · 2026-08-17&quot;">​</a></h1><blockquote><p>截至 2026-08-17。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="英伟达向软银数据中心开发商投资15亿美元-确保芯片供应openai项目" tabindex="-1">英伟达向软银数据中心开发商投资15亿美元，确保芯片供应OpenAI项目 <a class="header-anchor" href="#英伟达向软银数据中心开发商投资15亿美元-确保芯片供应openai项目" aria-label="Permalink to &quot;英伟达向软银数据中心开发商投资15亿美元，确保芯片供应OpenAI项目&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-17">2026-08-17</time></p><p><img src="'+s+'" alt="配图"></p><p>英伟达宣布向软银旗下数据中心开发商投资15亿美元，此举将确保其芯片用于OpenAI的数据中心项目。该投资进一步巩固了英伟达在AI算力基础设施领域的地位，并深化了与软银及OpenAI的合作关系。对读者：关注英伟达在AI基础设施领域的投资动向，可能影响未来GPU供应格局。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/17/nvidia-investing-1-5b-in-softbank-data-center-developer-behind-openai-project/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="语音ai公司wispr融资2-8亿美元-估值达20亿美元-拓展会议记录等新领域" tabindex="-1">语音AI公司Wispr融资2.8亿美元，估值达20亿美元，拓展会议记录等新领域 <a class="header-anchor" href="#语音ai公司wispr融资2-8亿美元-估值达20亿美元-拓展会议记录等新领域" aria-label="Permalink to &quot;语音AI公司Wispr融资2.8亿美元，估值达20亿美元，拓展会议记录等新领域&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-17">2026-08-17</time></p><p><img src="'+i+'" alt="配图"></p><p>语音AI初创公司Wispr完成2.8亿美元融资，估值达到20亿美元。资金将用于拓展新业务领域，包括新推出的会议记录工具。Wispr此前以语音输入法Flow闻名，此次融资显示其正从单一产品向更广泛的AI语音应用场景扩张。对读者：关注Wispr在会议记录等新领域的进展，可能对现有办公工具市场带来冲击。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/17/wispr-raises-280m-at-2b-valuation-as-it-looks-beyond-dictation/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="stripe拟以70亿美元以上收购ai网关初创公司openrouter" tabindex="-1">Stripe拟以70亿美元以上收购AI网关初创公司OpenRouter <a class="header-anchor" href="#stripe拟以70亿美元以上收购ai网关初创公司openrouter" aria-label="Permalink to &quot;Stripe拟以70亿美元以上收购AI网关初创公司OpenRouter&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-17">2026-08-17</time></p><p><img src="'+o+'" alt="配图"></p><p>据传Stripe已达成协议，以超过70亿美元的价格收购AI网关初创公司OpenRouter。OpenRouter的CEO曾将公司描述为“AI领域的Stripe”，此次收购将帮助Stripe进入AI模型分发和支付领域。对读者：关注Stripe在AI领域的布局，可能影响AI模型API的定价和分发方式。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/16/stripe-will-reportedly-acquire-ai-gateway-startup-openrouter-for-7b/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="anthropic-ceo称ai反弹-根本上是信任危机" tabindex="-1">Anthropic CEO称AI反弹“根本上是信任危机” <a class="header-anchor" href="#anthropic-ceo称ai反弹-根本上是信任危机" aria-label="Permalink to &quot;Anthropic CEO称AI反弹“根本上是信任危机”&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-17">2026-08-17</time></p><p><img src="'+p+'" alt="配图"></p><p>Anthropic CEO Dario Amodei回应外界对其AI悲观论的批评，称当前AI反弹“根本上是信任危机”。他否认自己描绘了过于悲观的AI前景，并强调需要重建公众对AI的信任。对读者：了解AI行业领袖对信任危机的看法，有助于把握AI伦理和监管讨论的走向。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/16/anthropic-ceo-says-ai-backlash-is-fundamentally-a-crisis-of-trust/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="openai据报解散预备队团队-安全职责分散至现有团队" tabindex="-1">OpenAI据报解散预备队团队，安全职责分散至现有团队 <a class="header-anchor" href="#openai据报解散预备队团队-安全职责分散至现有团队" aria-label="Permalink to &quot;OpenAI据报解散预备队团队，安全职责分散至现有团队&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-08-17">2026-08-17</time></p><p><img src="'+c+'" alt="配图"></p><p>据金融时报报道，OpenAI在上月底解散了其预备队团队，该团队负责评估模型风险并制定缓解措施。职责已分散到生物、网络等特定领域并并入现有团队。这是OpenAI在IPO前安全团队的最新变动。对读者：关注OpenAI安全治理架构的变化，可能影响其模型发布和风险评估流程。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/980817/openai-disbands-preparedness-team" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="anthropic详解claude隐形文本水印技术-采用synthid-text方案" tabindex="-1">Anthropic详解Claude隐形文本水印技术，采用SynthID-Text方案 <a class="header-anchor" href="#anthropic详解claude隐形文本水印技术-采用synthid-text方案" aria-label="Permalink to &quot;Anthropic详解Claude隐形文本水印技术，采用SynthID-Text方案&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-08-17">2026-08-17</time></p><p><img src="'+l+'" alt="配图"></p><p>Anthropic澄清了计划如何为Claude生成的文本应用隐形水印，以符合欧洲AI透明度规则。该系统基于Google DeepMind的开源水印技术SynthID-Text，通过用词概率创建可检测模式。该功能与C2PA图像支持一同推出，旨在满足欧盟AI法案要求。对读者：了解AI文本水印技术，有助于识别AI生成内容，并评估其对内容创作的影响。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/980869/anthropic-claude-watermarks-synthid-text-system" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="openai加入ports-pike项目-投资俄亥俄州数据中心园区" tabindex="-1">OpenAI加入PORTS-Pike项目，投资俄亥俄州数据中心园区 <a class="header-anchor" href="#openai加入ports-pike项目-投资俄亥俄州数据中心园区" aria-label="Permalink to &quot;OpenAI加入PORTS-Pike项目，投资俄亥俄州数据中心园区&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-08-17">2026-08-17</time></p><p><img src="'+h+'" alt="配图"></p><p>OpenAI宣布加入PORTS-Pike技术园区项目，与SB Energy、NVIDIA和美国能源部合作，在俄亥俄州派克县建设约8吉瓦的数据中心。项目预计创造3.5万个建筑岗位和2500个长期岗位，并承诺支付项目特定能源和基础设施成本。对读者：关注OpenAI在基础设施上的大规模投资，可能影响AI算力供应和区域经济。</p><p class="news-entry-source"><a href="https://openai.com/index/openai-joins-ports-pike-project" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="google-gemini与pixel携手五大足球俱乐部-提升球迷观赛体验" tabindex="-1">Google Gemini与Pixel携手五大足球俱乐部，提升球迷观赛体验 <a class="header-anchor" href="#google-gemini与pixel携手五大足球俱乐部-提升球迷观赛体验" aria-label="Permalink to &quot;Google Gemini与Pixel携手五大足球俱乐部，提升球迷观赛体验&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google AI Blog</span><time datetime="2026-08-17">2026-08-17</time></p><p><img src="'+d+'" alt="配图"></p><p>Google宣布Gemini和Pixel与五家全球足球俱乐部合作，通过AI和智能手机技术提升球迷的观赛日体验。合作将利用Gemini的AI能力为球迷提供个性化内容和互动功能。对读者：关注AI在体育领域的应用案例，可能为其他行业提供AI用户体验设计的参考。</p><p class="news-entry-source"><a href="https://blog.google/products-and-platforms/products/gemini/google-gemini-pixel-football-club-partnerships/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="阿里发布笔记本电脑级ai模型-回应meta挑战" tabindex="-1">阿里发布笔记本电脑级AI模型，回应Meta挑战 <a class="header-anchor" href="#阿里发布笔记本电脑级ai模型-回应meta挑战" aria-label="Permalink to &quot;阿里发布笔记本电脑级AI模型，回应Meta挑战&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Tech Buzz</span><time datetime="2026-08-17">2026-08-17</time></p><p>阿里巴巴发布了一款适用于笔记本电脑的AI模型，直接回应Meta的类似产品。该模型旨在在消费级硬件上运行，提供高效性能。此举加剧了AI模型在端侧部署的竞争。对读者：关注端侧AI模型的发展，可能为开发者和用户带来更多本地化AI应用选择。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMijwFBVV95cUxPVW9fYnhYdkRHM3pXNkh1REpCOUhnTi1Wd01yaHVfSjFLbnhhTVY5enpDWTJSSFR5cWRHaHg0aDNPNC1HU3pqUTdTMS00NFIxaVFKYW1CcTRBUUZOZ1QxYkVSb2FJdDBDdWptRFRSM0ZWd0Frdi01VkY2VDZQSjVfcnNvdXJjekUtVmFRcHlZTQ?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="阿里巴巴发布旗舰qwen3-8-max模型权重" tabindex="-1">阿里巴巴发布旗舰Qwen3.8-Max模型权重 <a class="header-anchor" href="#阿里巴巴发布旗舰qwen3-8-max模型权重" aria-label="Permalink to &quot;阿里巴巴发布旗舰Qwen3.8-Max模型权重&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">silicon.co.uk</span><time datetime="2026-08-17">2026-08-17</time></p><p>阿里巴巴发布了其旗舰AI模型Qwen3.8-Max的权重，采用开源方式。该模型在多项基准测试中表现出色，可能对现有闭源模型构成挑战。对读者：关注Qwen3.8-Max的开源发布，可能为开发者提供高性能模型的替代选择。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const x=a(m,[["render",u]]);export{k as __pageData,x as default};
